var i=`0225-polvo-a-lagareiro`;var n=`world-0225`;var a=`PT`;var o=`southern-europe`;var r=4;var l=107;var s={en:`Polvo à Lagareiro`,ua:`Восьминіг лагарейру`};var u={en:`A traditional Portugal dish made with octopus, bay leaf, new potato, garlic. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Португалія. Основні інгредієнти: восьминіг, лавровий лист, молода картопля, часник. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Cook the listed ingredients in simmering water for about 55 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 55 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:55,i:[[`octopus`,900,`g`],[`water`,1200,`ml`],[`bay-leaf`,1,`leaf`]]},{en:`Cut the vegetables evenly and roast at 200°C for about 35 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 35 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:35,i:[[`new-potato`,700,`g`],[`garlic`,7,`clove`],[`extra-virgin-olive-oil`,105,`ml`]]},{en:`Roast in a preheated 190°C oven for about 15 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 15 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:15,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,20,`g`],[`lemon-juice`,20,`ml`],[`table-salt`,null,`to_taste`]]}];var g={slug:i,id:n,country:`PT`,region:o,servings:4,minutes:107,title:s,text:u,steps:d};export{a as country,g as default,n as id,l as minutes,o as region,r as servings,i as slug,d as steps,u as text,s as title};